INSERT INTO settings (key, value) VALUES ('seo', '{"home":{"title":"Ovenroma Bakers — Freshly Baked Biscuits, Muffins, Kulcha & Gift Hampers","description":"Order freshly baked vegetarian bakery products online from Ovenroma Bakers: artisanal biscuits, muffins, Amritsari kulcha, veg patties, gluten-free namkeen and flours, festival hampers and bulk orders."},"shop":{"title":"Shop Bakery Products Online — Biscuits, Muffins, Namkeen | Ovenroma Bakers","description":"Browse every Ovenroma Bakers product: eggless biscuits and cookies, muffins, kulcha, veg patties, gluten-free namkeen and atta. 100% vegetarian, freshly baked."},"gluten-free":{"title":"Gluten-Free Biscuits, Namkeen & Flours | Ovenroma Bakers","description":"Shop the Ovenroma Bakers gluten-free range: gluten-free biscuits and cookies, chocolate muffins, namkeen and stone-milled gluten-free atta and flours."},"bulk":{"title":"Langar & Bhandara Bulk Orders — Kulcha, Veg Patties, Biscuits | Ovenroma Bakers","description":"Fresh bakery products for Langar, Bhandara, gurudwara and temple events at bulk prices: kulcha ₹20/dozen, veg patties ₹8/piece, biscuits ₹180/kg, cupcakes ₹3/piece. Calculate and enquire on WhatsApp."},"hampers":{"title":"Festival Gift Hampers — Diwali, Rakhi, Corporate & Wedding | Ovenroma Bakers","description":"Thoughtfully curated bakery gift hampers for Diwali, Christmas, New Year, Rakhi, weddings, birthdays and corporate gifting. Customise products, packaging and message."},"about":{"title":"About Ovenroma Bakers — Freshly Baked Happiness","description":"Ovenroma Bakers bakes 100% vegetarian biscuits, muffins, kulchas and savouries, with a dedicated gluten-free range and affordable bulk orders for every occasion."},"contact":{"title":"Contact Ovenroma Bakers — Orders, Bulk & Corporate Enquiries","description":"Get in touch with Ovenroma Bakers for orders, Langar & Bhandara bulk orders, festival hampers and corporate gifting. Message us on WhatsApp or send an enquiry."}}');
